KG42.register("rules-66c175c046d077c516bb419b",{"id":"48-multiple_energy_carrier_market::v141-c-R001","paper":"48-multiple_energy_carrier_market","record":{"rule_id":"v141-c-R001","mechanism_id":"v141-a-M01","name":"Demand submission","process_stage":"bidding","market_meaning":"The preceding local market clearing occurs before a demand-bid update made between successive clearings. Scope: Demand-bid updates between successive local market clearings in the rolling trading horizon. Condition: If an agent exercises the permission to update a demand bid between successive market clearings. Each demand bid specifies an energy carrier, delivery-hour, supply-or-demand designation and network location, and contains one quantity in kWh and one valuation. Scope: Individual demand-bid format in the proposed local market. Agents submit separate demand bids for separate time-periods. Scope: Demand submissions for distinct delivery time-periods. Demand bids are submitted once per hour shortly before each delivery-hour, and submissions cover all hours in the trading horizon. Scope: Demand submission schedule and trading-horizon coverage in the described hourly implementation. Condition: For the described 1 h time-period implementation; the source also permits longer or shorter time-periods. Agents may construct step-function demand-bid curves by submitting multiple bids with different quantities and valuations without using bid dependencies. Scope: Construction of demand-bid curves from multiple individual submissions. Agents may connect demand bids with other bids using bid dependencies. Scope: Linked demand-bid submissions in the proposed market. Agents cannot submit indivisible demand bids requiring either full acceptance or no acceptance. Scope: Divisibility of demand bids in the proposed market. A demand bid for one hour cannot be conditioned on another hour's outcome within the same market clearing. Scope: Cross-hour demand-bid conditions within a single market clearing.","independence_rationale":"Relations governed by the approved function bidding.demand under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","clearing.local"],"E":[{"edge_id":"v141-c-R001-E001","source":"clearing.local","target":"bidding.demand","type":"precedes","constraint_ids":["v141-c-R001-C001"],"evidence_ids":["v141-b-g01-E014"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Construction of demand-bid curves from multiple individual submissions. | Cross-hour demand-bid conditions within a single market clearing. | Demand submission schedule and trading-horizon coverage in the described hourly implementation. | Demand submissions for distinct delivery time-periods. | Demand-bid updates between successive local market clearings in the rolling trading horizon. | Divisibility of demand bids in the proposed market. | Individual demand-bid format in the proposed local market. | Linked demand-bid submissions in the proposed market.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E012","v141-b-g01-E013","v141-b-g01-E014","v141-b-g01-E015","v141-b-g01-E017","v141-b-g01-E020","v141-b-g02-E22","v141-b-g02-E25"]},"x":[],"theta":[],"phi":[{"constraint_id":"v141-c-R001-C001","kind":"procedural","role":"core","statement":"The preceding local market clearing occurs before a demand-bid update made between successive clearings. Scope: Demand-bid updates between successive local market clearings in the rolling trading horizon. Condition: If an agent exercises the permission to update a demand bid between successive market clearings.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.local","bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E014"]},{"constraint_id":"v141-c-R001-C002","kind":"procedural","role":"core","statement":"Each demand bid specifies an energy carrier, delivery-hour, supply-or-demand designation and network location, and contains one quantity in kWh and one valuation. Scope: Individual demand-bid format in the proposed local market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E015"]},{"constraint_id":"v141-c-R001-C003","kind":"procedural","role":"core","statement":"Agents submit separate demand bids for separate time-periods. Scope: Demand submissions for distinct delivery time-periods.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E012"]},{"constraint_id":"v141-c-R001-C004","kind":"procedural","role":"core","statement":"Demand bids are submitted once per hour shortly before each delivery-hour, and submissions cover all hours in the trading horizon. Scope: Demand submission schedule and trading-horizon coverage in the described hourly implementation. Condition: For the described 1 h time-period implementation; the source also permits longer or shorter time-periods.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E012","v141-b-g01-E013","v141-b-g01-E014"]},{"constraint_id":"v141-c-R001-C005","kind":"procedural","role":"core","statement":"Agents may construct step-function demand-bid curves by submitting multiple bids with different quantities and valuations without using bid dependencies. Scope: Construction of demand-bid curves from multiple individual submissions.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E020"]},{"constraint_id":"v141-c-R001-C006","kind":"procedural","role":"core","statement":"Agents may connect demand bids with other bids using bid dependencies. Scope: Linked demand-bid submissions in the proposed market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E017"]},{"constraint_id":"v141-c-R001-C007","kind":"procedural","role":"core","statement":"Agents cannot submit indivisible demand bids requiring either full acceptance or no acceptance. Scope: Divisibility of demand bids in the proposed market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E22"]},{"constraint_id":"v141-c-R001-C008","kind":"procedural","role":"core","statement":"A demand bid for one hour cannot be conditioned on another hour's outcome within the same market clearing. Scope: Cross-hour demand-bid conditions within a single market clearing.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E25"]}],"pi":[{"evidence_id":"v141-b-g01-E012","location":{"location_id":"src-ec182c21f1-p03-c2r3__v141-a-M01-bidding","page":3,"printed_page":null,"section":null,"anchor_text":"4.1.3. Rolling time-horizon a- Energy is traded for discrete time-periods, and the time-periodn- len","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Energy is traded for discrete time-periods, and the time-period length is the same for all energy carriers. Energy in different time-periods are traded as different commodities, and agents submit separate bids for separate time-periods. For clarity, we will here assume that the time-period length is 1 h. However, the time-period length could be both longer and shorter."},{"evidence_id":"v141-b-g01-E013","location":{"location_id":"src-ec182c21f1-p03-c2r3__v141-a-M01-settlement","page":3,"printed_page":null,"section":null,"anchor_text":"4.1.3. Rolling time-horizon a- Energy is traded for discrete time-periods, and the time-periodn- len","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"condition"},"source_text":"In order to minimize forecast errors, bid submission and market clearing take place as close to the delivery-hour as possible. Therefore, bids are submitted and the market is cleared once per hour, shortly before the beginning of each delivery-hour. However, for the market to be able to accommodate dependencies over longer periods of time, each market clearing also includes a range of future hours. The full range of hours included in a market clearing is referred to as the trading horizon. The first hour in the trading horizon (the upcoming delivery-hour) is referred to as the binding hour, and subsequent hours are referred to as advisory hours. As the names indicate, the market results for the binding hour are final, whereas the results for the advisory hours will be updated in subsequent market clearings."},{"evidence_id":"v141-b-g01-E014","location":{"location_id":"src-ec182c21f1-p04-c1r1__v141-a-M01-bidding","page":4,"printed_page":null,"section":null,"anchor_text":"M. Brolin and H. Pihl agents submit bids for all hours in the trading horizon, and they are 4. allow","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"agents submit bids for all hours in the trading horizon, and they are allowed to update their bids between market clearings."},{"evidence_id":"v141-b-g01-E015","location":{"location_id":"src-ec182c21f1-p04-c1r2__v141-a-M01-bidding","page":4,"printed_page":null,"section":null,"anchor_text":"energy will be injected or withdrawn). In addition, each bid states a 4. single quantity (in kWh) an","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"In the proposed market design, each individual bid has a very simple structure. Each bid contains basic information about what the bid is for (i.e. it specifies an energy carrier, a delivery-hour, whether it is a supply or demand bid, and the location on the network where the energy will be injected or withdrawn). In addition, each bid states a single quantity (in kWh) and a single valuation (in €/kWh)."},{"evidence_id":"v141-b-g01-E017","location":{"location_id":"src-ec182c21f1-p04-c1r2__v141-a-M01-bidding","page":4,"printed_page":null,"section":null,"anchor_text":"energy will be injected or withdrawn). In addition, each bid states a 4. single quantity (in kWh) an","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"One central ingredient in the described market design is the possibility to connect bids using bid dependencies, enabling agents to create links between bids. The bids can in this respect be viewed as atoms that can be tied together using bid dependencies to create complex molecules. This can be applied for various purposes, such as an instrument for providing flexibility to the market. There are five types of bid dependencies implemented in the market clearing:"},{"evidence_id":"v141-b-g01-E020","location":{"location_id":"src-ec182c21f1-p04-c1r3__v141-a-M01-bidding","page":4,"printed_page":null,"section":null,"anchor_text":"GE-dependencies: The sum of the accepted quantity from the bids qb • should be greater than or equal","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"example"},"source_text":"Note that agents can construct some bid combinations without the need to use bid dependencies. For example, step-function bid curves can be built by simply submitting multiple bids with different quantities and valuations."},{"evidence_id":"v141-b-g02-E22","location":{"location_id":"src-ec182c21f1-p08-c1r4__v141-a-M01-pricing","page":8,"printed_page":null,"section":"6.1. The indivisibility issue","anchor_text":"producer may have a minimum load requirement such that it has to either be turned oﬀor operate above","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"exception"},"source_text":"As described in 4.2, the market optimization problem is linear and no integer variables are introduced. This means that there is no possibility for agents to submit indivisible bids, i.e. bids that should be either fully accepted or not accepted at all."},{"evidence_id":"v141-b-g02-E25","location":{"location_id":"src-ec182c21f1-p08-c2r4__v141-a-M01-bidding","page":8,"printed_page":null,"section":"6.3. Multiple energy carriers and flexibility instruments","anchor_text":"to Even though the proposed ﬂexibility instruments provide a vast list le of options and possibiliti","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"exception"},"source_text":"Even though the proposed flexibility instruments provide a vast list of options and possibilities, there are limitations in what they can represent. For example, since agents cannot submit indivisible bids, the possibility for a market participant to completely switch between electricity and DH cannot be ensured, i.e. it cannot be ensured that only one of these options exclusively will be cleared. Another limitation is the difficulty to construct bids for energy storage that takes full advantage of the flexibility offered by such assets. Although it is possible to construct bids and bid dependencies that represent a specific charge and discharge cycle, it is difficult to fully capture all possibilities and constraints of a typical energy storage. Accurately capturing all possible charge and discharge possibilities over a trading horizon would require a very large number of bids and bid dependencies. Further, the available capacity for hours further out in the horizon depends on the amount cleared in prior hours. However, it is not possible to condition the bids in one hour on the outcomes of another hour within the same market clearing."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":"No design-selection or operational decision variable is defined for this procedural/admission rule. C1 declares no x objects. Source quantities such as bid quantity and valuation are bid attributes used by the bid-format and clearing descriptions, but their optimization role and domain for demand submission are not defined within this rule.","empty_theta_reason":"No fixed numeric coefficient, bound, capacity, or exogenous parameter is defined for this rule. The source states units for bid quantity (kWh) and valuation (in currency/kWh), but the frozen graph declares no typed parameter object, and no value or domain is supplied for a demand-submission parameter."},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-settlement"],"extras":{"decision_anchor":"bidding.demand","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E014","quote":"agents submit bids for all hours in the trading horizon, and they are allowed to update their bids between market clearings."}],[{"evidence_id":"v141-b-g01-E015","quote":"Each bid contains basic information about what the bid is for (i.e. it specifies an energy carrier, a delivery-hour, whether it is a supply or demand bid, and the location on the network where the energy will be injected or withdrawn). In addition, each bid states a single quantity (in kWh) and a single valuation (in €/kWh)."}],[{"evidence_id":"v141-b-g01-E012","quote":"Energy in different time-periods are traded as different commodities, and agents submit separate bids for separate time-periods."}],[{"evidence_id":"v141-b-g01-E012","quote":"For clarity, we will here assume that the time-period length is 1 h. However, the time-period length could be both longer and shorter."},{"evidence_id":"v141-b-g01-E013","quote":"Therefore, bids are submitted and the market is cleared once per hour, shortly before the beginning of each delivery-hour."},{"evidence_id":"v141-b-g01-E014","quote":"agents submit bids for all hours in the trading horizon"}],[{"evidence_id":"v141-b-g01-E020","quote":"Note that agents can construct some bid combinations without the need to use bid dependencies. For example, step-function bid curves can be built by simply submitting multiple bids with different quantities and valuations."}],[{"evidence_id":"v141-b-g01-E017","quote":"One central ingredient in the described market design is the possibility to connect bids using bid dependencies, enabling agents to create links between bids."}],[{"evidence_id":"v141-b-g02-E22","quote":"As described in 4.2, the market optimization problem is linear and no integer variables are introduced. This means that there is no possibility for agents to submit indivisible bids, i.e. bids that should be either fully accepted or not accepted at all."}],[{"evidence_id":"v141-b-g02-E25","quote":"However, it is not possible to condition the bids in one hour on the outcomes of another hour within the same market clearing."}]],"C2_formalization":{"graph_sha256":"4b69fd16515a82aa7c895e541f646d35ad236115542c21c296eeb58d46ac4c76","applicability":"non_mathematical","reason":"This frozen rule captures demand-bid submission as procedural/admission requirements: update timing relative to local clearing, required bid fields, separate bids for separate time-periods, hourly submission and trading-horizon coverage, optional step-curve construction, optional bid dependencies, prohibition of indivisible bids, and no cross-hour conditioning within a clearing. The supplied source text for this rule does not provide an equation defining the demand-submission act itself; the mathematical clearing, objective, dependency and pricing formulas belong to other rules. With only bidding.demand and clearing.local in the frozen graph and no C1-declared x/theta, no source-supported mathematical expression is available. B evidence remains unreviewed in this experiment.","bindings":[],"revision_requests":[]}},"quarantined_references":[]}});
